def check(vad):
    prot = vad.protection
    if not ('EXECUTE' in prot and 'WRITE' in prot):
        if 'EXECUTE' in prot and vad.has_dirty_page():
            pass                      # written after mapping
        else:
            return None               # not suspicious
    private = vad.private and vad.tag == 'VadS'
    odd_map = (not vad.private) and prot != 'PAGE_EXECUTE_WRITECOPY'
    if not (private or odd_map):
        return None
    if vad.all_zero_or_paged_out():
        return None
    head = vad.read(64)
    note = 'MZ header' if head[:2] == b'MZ' else None
    return (vad.start, prot, note, head)
